package ec.edu.scli.reservas.application.service;

import ec.edu.scli.reservas.client.*; import ec.edu.scli.reservas.domain.model.*; import ec.edu.scli.reservas.domain.port.out.*; import ec.edu.scli.reservas.infrastructure.persistence.entity.*; import ec.edu.scli.reservas.infrastructure.persistence.repository.*; import ec.edu.scli.reservas.presentation.dto.request.*; import ec.edu.scli.reservas.presentation.dto.response.*; import ec.edu.scli.reservas.presentation.exception.ResourceNotFoundException; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;

@Service public class SolicitudCambioPlanificacionService {
 private final SolicitudCambioPlanificacionJpaRepository solicitudes; private final RevisionSolicitudCambioJpaRepository revisiones; private final PlanificacionAgregadaJpaRepository planes; private final PlanificacionJpaRepository bloques; private final ActorActualPort actores; private final ContextoInstitucionalPort contextos; private final PoliticaAmbitoLaboratorio ambito; private final AcademicoLaboratoriosClient academico; private final UsuariosClient usuarios; private final NotificacionService notificaciones; private final PlanificacionAgregadaService disponibilidad;
 public SolicitudCambioPlanificacionService(SolicitudCambioPlanificacionJpaRepository s,RevisionSolicitudCambioJpaRepository r,PlanificacionAgregadaJpaRepository p,PlanificacionJpaRepository b,ActorActualPort a,ContextoInstitucionalPort c,PoliticaAmbitoLaboratorio am,AcademicoLaboratoriosClient ac,UsuariosClient u,NotificacionService n,PlanificacionAgregadaService d){solicitudes=s;revisiones=r;planes=p;bloques=b;actores=a;contextos=c;ambito=am;academico=ac;usuarios=u;notificaciones=n;disponibilidad=d;}
 @Transactional public SolicitudCambioResponse crear(UUID planId,CrearSolicitudCambioRequest req){var actor=actores.obtener();if(!actor.tiene("ROLE_COORDINADOR"))throw new AccessDeniedException("Solo el coordinador puede solicitar cambios");var plan=plan(planId);var ctx=contextos.obtenerPorPerfilId(actor.perfilId());if(ctx==null||!ctx.carreraIds().contains(plan.getCarreraId()))throw new AccessDeniedException("La planificacion no pertenece a su carrera");if(plan.getEstado()!=EstadoPlanificacionAgregada.APROBADA)throw new IllegalStateException("Solo una planificacion aprobada admite solicitudes de cambio");var periodo=academico.obtenerPeriodo(plan.getPeriodoId());if(periodo!=null&&periodo.fechaFin()!=null&&periodo.fechaFin().isBefore(LocalDate.now(ZoneId.of("America/Guayaquil"))))throw new IllegalStateException("Una planificacion finalizada es historica");var b=bloques.findById(req.bloqueId()).orElseThrow(()->new ResourceNotFoundException("Bloque no encontrado"));if(!planId.equals(b.getPlanificacionId()))throw new IllegalArgumentException("El bloque no pertenece a la planificacion");if(solicitudes.existsByBloqueIdAndEstado(b.getId(),EstadoSolicitudCambio.PENDIENTE))throw new IllegalStateException("El bloque ya tiene una solicitud pendiente");validarPropuesta(req,b);
  var s=new SolicitudCambioPlanificacionJpaEntity();s.setPlanificacionId(planId);s.setBloqueId(b.getId());s.setTipo(req.tipo());s.setMotivo(req.motivo().trim());s.setSolicitantePerfilId(actor.perfilId());s.setLaboratorioAnteriorId(b.getLaboratorioId());s.setLaboratorioPropuestoId(req.tipo()==TipoSolicitudCambio.LABORATORIO?req.laboratorioId():b.getLaboratorioId());s.setDocenteAnteriorId(b.getDocenteId());s.setDocentePropuestoId(req.tipo()==TipoSolicitudCambio.DOCENTE?req.docenteId():b.getDocenteId());s.setDiaAnterior(b.getDiaSemana());s.setDiaPropuesto(req.tipo()==TipoSolicitudCambio.HORARIO?req.diaSemana():b.getDiaSemana());s.setHoraInicioAnterior(b.getHoraInicio());s.setHoraInicioPropuesta(req.tipo()==TipoSolicitudCambio.HORARIO?req.horaInicio():b.getHoraInicio());s.setHoraFinAnterior(b.getHoraFin());s.setHoraFinPropuesta(req.tipo()==TipoSolicitudCambio.HORARIO?req.horaFin():b.getHoraFin());s=solicitudes.saveAndFlush(s);
  Set<UUID> pisos=new LinkedHashSet<>();pisos.add(piso(b.getLaboratorioId()));if(req.tipo()==TipoSolicitudCambio.LABORATORIO)pisos.add(piso(req.laboratorioId()));for(UUID piso:pisos){var admins=usuarios.obtenerAdministradoresPorPiso(piso);if(admins.isEmpty())throw new IllegalStateException("No existe administrador asignado al piso "+piso);var rev=new RevisionSolicitudCambioJpaEntity();rev.setSolicitudId(s.getId());rev.setPisoId(piso);revisiones.save(rev);UUID sid=s.getId();admins.forEach(perfil->notificaciones.notificarPerfilIdempotente(perfil,"CAMBIO:NUEVO:"+sid+":"+perfil,"Nueva solicitud de cambio por revisar",req.motivo(),Map.of("tipo","SOLICITUD_CAMBIO","referenciaId",sid.toString())));}
  return response(s);
 }
 @Transactional(readOnly=true) public List<SolicitudCambioResponse> listar(UUID planId){var actor=actores.obtener();var items=solicitudes.findByPlanificacionIdOrderByCreadaEnDesc(planId);if(actor.tiene("ROLE_ADMINISTRADOR_PISO")){UUID piso=ambito.pisoGestionado();items=items.stream().filter(s->revisiones.findBySolicitudIdAndPisoId(s.getId(),piso).isPresent()).toList();}else if(actor.tiene("ROLE_COORDINADOR")){var p=plan(planId);var ctx=contextos.obtenerPorPerfilId(actor.perfilId());if(ctx==null||!ctx.carreraIds().contains(p.getCarreraId()))throw new AccessDeniedException("Fuera del ambito de carrera");}else if(!actor.tiene("ROLE_ADMINISTRADOR"))throw new AccessDeniedException("No puede consultar solicitudes");return items.stream().map(this::response).toList();}
 @Transactional public SolicitudCambioResponse aprobar(UUID id,String observacion){var s=pendiente(id);var actor=actores.obtener();UUID piso=ambito.pisoGestionado();var rev=revisiones.findBySolicitudIdAndPisoId(id,piso).orElseThrow(()->new AccessDeniedException("La solicitud no corresponde a su piso"));rev.setEstado(EstadoSolicitudCambio.APROBADA);rev.setRevisorPerfilId(actor.perfilId());rev.setObservacion(observacion);rev.setResueltaEn(Instant.now());revisiones.saveAndFlush(rev);if(revisiones.findBySolicitudId(id).stream().allMatch(r->r.getEstado()==EstadoSolicitudCambio.APROBADA))aplicar(s);return response(s);}
 @Transactional public SolicitudCambioResponse rechazar(UUID id,String observacion){if(observacion==null||observacion.isBlank())throw new IllegalArgumentException("El rechazo requiere observacion");var s=pendiente(id);var actor=actores.obtener();UUID piso=ambito.pisoGestionado();var rev=revisiones.findBySolicitudIdAndPisoId(id,piso).orElseThrow(()->new AccessDeniedException("La solicitud no corresponde a su piso"));rev.setEstado(EstadoSolicitudCambio.RECHAZADA);rev.setRevisorPerfilId(actor.perfilId());rev.setObservacion(observacion);rev.setResueltaEn(Instant.now());revisiones.saveAndFlush(rev);s.setEstado(EstadoSolicitudCambio.RECHAZADA);s.setResolucion(observacion);s.setResueltaEn(Instant.now());solicitudes.save(s);avisarCoordinador(s,"Solicitud de cambio rechazada");return response(s);}
 private void aplicar(SolicitudCambioPlanificacionJpaEntity s){var plan=plan(s.getPlanificacionId());if(plan.getEstado()!=EstadoPlanificacionAgregada.APROBADA)throw new IllegalStateException("La planificacion ya no admite cambios");var periodo=academico.obtenerPeriodo(plan.getPeriodoId());if(periodo!=null&&periodo.fechaFin()!=null&&periodo.fechaFin().isBefore(LocalDate.now(ZoneId.of("America/Guayaquil"))))throw new IllegalStateException("La planificacion ya finalizo");if(s.getTipo()==TipoSolicitudCambio.DOCENTE&&!usuarios.docentePerteneceCarrera(s.getDocentePropuestoId(),plan.getCarreraId()))throw new IllegalStateException("El docente propuesto no pertenece a la carrera");var b=bloques.findById(s.getBloqueId()).orElseThrow();if(s.getTipo()==TipoSolicitudCambio.CANCELACION)b.setEstado(EstadoPlanificacion.CANCELADA);else {b.setLaboratorioId(s.getLaboratorioPropuestoId());b.setDocenteId(s.getDocentePropuestoId());b.setDiaSemana(s.getDiaPropuesto());b.setHoraInicio(s.getHoraInicioPropuesta());b.setHoraFin(s.getHoraFinPropuesta());var activos=bloques.findByPlanificacionId(plan.getId()).stream().filter(x->x.getEstado()!=EstadoPlanificacion.CANCELADA).toList();disponibilidad.validarOcupacionOficial(plan,activos);}b.setActualizadaEn(Instant.now());bloques.saveAndFlush(b);s.setEstado(EstadoSolicitudCambio.APROBADA);s.setResolucion("Aprobada por todos los pisos afectados");s.setResueltaEn(Instant.now());solicitudes.save(s);avisarCoordinador(s,"Solicitud de cambio aprobada");usuarios.obtenerEstudiantesCompatibles(plan.getCarreraId(),plan.getPeriodoId(),b.getNivel()).forEach(perfil->notificaciones.notificarPerfilIdempotente(perfil,"CAMBIO:ESTUDIANTE:"+s.getId()+":"+perfil,"Cambio de horario aprobado","Revise su horario academico actualizado",Map.of("tipo","CAMBIO_HORARIO","planificacionId",s.getPlanificacionId().toString())));Set<UUID> docentes=new HashSet<>();if(s.getDocenteAnteriorId()!=null)docentes.add(s.getDocenteAnteriorId());if(s.getDocentePropuestoId()!=null)docentes.add(s.getDocentePropuestoId());docentes.stream().map(usuarios::obtenerDocentePorId).filter(Objects::nonNull).forEach(d->notificaciones.notificarPerfilIdempotente(d.perfilId(),"CAMBIO:DOCENTE:"+s.getId()+":"+d.perfilId(),"Cambio de horario aprobado","Revise su horario academico actualizado",Map.of("tipo","CAMBIO_HORARIO","planificacionId",s.getPlanificacionId().toString())));}
 private void avisarCoordinador(SolicitudCambioPlanificacionJpaEntity s,String titulo){UUID perfil=plan(s.getPlanificacionId()).getCoordinadorPerfilId();notificaciones.notificarPerfilIdempotente(perfil,"CAMBIO:RESUELTO:"+s.getId()+":"+s.getEstado(),titulo,s.getMotivo(),Map.of("tipo","SOLICITUD_CAMBIO_RESUELTA","referenciaId",s.getId().toString()));}
 private void validarPropuesta(CrearSolicitudCambioRequest r,PlanificacionJpaEntity b){switch(r.tipo()){case LABORATORIO->{if(r.laboratorioId()==null||r.laboratorioId().equals(b.getLaboratorioId()))throw new IllegalArgumentException("Debe proponer otro laboratorio");}case DOCENTE->{if(r.docenteId()==null||r.docenteId().equals(b.getDocenteId()))throw new IllegalArgumentException("Debe proponer otro docente");}case HORARIO->{if(r.diaSemana()==null||r.horaInicio()==null||r.horaFin()==null||!r.horaInicio().isBefore(r.horaFin()))throw new IllegalArgumentException("Debe proponer un horario valido");}case CANCELACION->{}}}
 private UUID piso(UUID lab){var l=academico.obtenerLaboratorio(lab);if(l==null||!l.existe())throw new IllegalArgumentException("Laboratorio inexistente");return l.pisoId();} private PlanificacionAgregadaJpaEntity plan(UUID id){return planes.findById(id).orElseThrow(()->new ResourceNotFoundException("Planificacion no encontrada"));} private SolicitudCambioPlanificacionJpaEntity pendiente(UUID id){var s=solicitudes.findById(id).orElseThrow(()->new ResourceNotFoundException("Solicitud no encontrada"));if(s.getEstado()!=EstadoSolicitudCambio.PENDIENTE)throw new IllegalStateException("La solicitud ya fue resuelta");return s;}
 private SolicitudCambioResponse response(SolicitudCambioPlanificacionJpaEntity s){return new SolicitudCambioResponse(s.getId(),s.getPlanificacionId(),s.getBloqueId(),s.getTipo().name(),s.getEstado().name(),s.getMotivo(),s.getSolicitantePerfilId(),s.getLaboratorioAnteriorId(),s.getLaboratorioPropuestoId(),s.getDocenteAnteriorId(),s.getDocentePropuestoId(),s.getDiaAnterior(),s.getDiaPropuesto(),s.getHoraInicioAnterior(),s.getHoraInicioPropuesta(),s.getHoraFinAnterior(),s.getHoraFinPropuesta(),s.getResolucion(),s.getCreadaEn(),s.getResueltaEn(),revisiones.findBySolicitudId(s.getId()).stream().map(r->new SolicitudCambioResponse.Revision(r.getPisoId(),r.getEstado().name(),r.getRevisorPerfilId(),r.getObservacion(),r.getResueltaEn())).toList());}
}
